/// Build an axum::Router for the `VideoApi` trait.
pub fn video_api_router<T>(api: T) -> ::axum::Router
where
    T: VideoApi + Clone + Send + Sync + 'static,
{
    ::axum::Router::new()
        .route(
            "/api/videos/{primaryKey}",
            ::axum::routing::delete(delete_video_handler::<T>),
        )
        .route("/api/videos/{primaryKey}", ::axum::routing::get(get_video_handler::<T>))
        .route("/api/videos", ::axum::routing::get(get_videos_handler::<T>))
        .route(
            "/api/videos/{primaryKey}",
            ::axum::routing::patch(patch_video_handler::<T>),
        )
        .route("/api/videos", ::axum::routing::post(post_videos_handler::<T>))
        .route(
            "/api/videos/{primaryKey}/audio-detector-claim",
            ::axum::routing::post(post_videos_audio_detector_claim_handler::<T>),
        )
        .route(
            "/api/videos/{primaryKey}/object-detector-claim",
            ::axum::routing::post(post_videos_object_detector_claim_handler::<T>),
        )
        .route(
            "/api/videos/{primaryKey}/object-tracker-claim",
            ::axum::routing::post(post_videos_object_tracker_claim_handler::<T>),
        )
        .layer(::axum::extract::DefaultBodyLimit::max(2097152usize))
        .with_state(api)
}
