/// Combined router spanning 10 traits: AudioDetectorClaimVideoApi, AudioEventApi, CameraApi, DetectionApi, ObjectDetectorClaimVideoApi, ObjectTrackerClaimVideoApi, SegmentProducerClaimCameraApi, StreamProducerClaimCameraApi, TrackApi, VideoApi.
pub fn build_router<T1, T2, T3, T4, T5, T6, T7, T8, T9, T10>(
    audio_detector_claim_video_api: T1,
    audio_event_api: T2,
    camera_api: T3,
    detection_api: T4,
    object_detector_claim_video_api: T5,
    object_tracker_claim_video_api: T6,
    segment_producer_claim_camera_api: T7,
    stream_producer_claim_camera_api: T8,
    track_api: T9,
    video_api: T10,
) -> ::axum::Router
where
    T1: AudioDetectorClaimVideoApi + Clone + Send + Sync + 'static,
    T2: AudioEventApi + Clone + Send + Sync + 'static,
    T3: CameraApi + Clone + Send + Sync + 'static,
    T4: DetectionApi + Clone + Send + Sync + 'static,
    T5: ObjectDetectorClaimVideoApi + Clone + Send + Sync + 'static,
    T6: ObjectTrackerClaimVideoApi + Clone + Send + Sync + 'static,
    T7: SegmentProducerClaimCameraApi + Clone + Send + Sync + 'static,
    T8: StreamProducerClaimCameraApi + Clone + Send + Sync + 'static,
    T9: TrackApi + Clone + Send + Sync + 'static,
    T10: VideoApi + Clone + Send + Sync + 'static,
{
    audio_detector_claim_video_api_router(audio_detector_claim_video_api)
        .merge(audio_event_api_router(audio_event_api))
        .merge(camera_api_router(camera_api))
        .merge(detection_api_router(detection_api))
        .merge(object_detector_claim_video_api_router(object_detector_claim_video_api))
        .merge(object_tracker_claim_video_api_router(object_tracker_claim_video_api))
        .merge(
            segment_producer_claim_camera_api_router(segment_producer_claim_camera_api),
        )
        .merge(stream_producer_claim_camera_api_router(stream_producer_claim_camera_api))
        .merge(track_api_router(track_api))
        .merge(video_api_router(video_api))
}
